class SinglyLinkedList:
    def __init__(self) -&gt; None:
        self.dummy = SinglyListNode(0)
        self.size = 0

    def __len__(self) -&gt; int:
        return self.size

    def _prev_node(self, index: int) -&gt; SinglyListNode:
        if not 0 &lt;= index &lt;= self.size:
            raise IndexError('index out of range')
        prev = self.dummy
        for _ in range(index):
            prev = prev.next
        return prev

    def append(self, val: Any) -&gt; None:
        self.insert(self.size, val)

    def prepend(self, val: Any) -&gt; None:
        self.insert(0, val)

    def insert(self, index: int, val: Any) -&gt; None:
        prev = self._prev_node(index)
        node = SinglyListNode(val, prev.next)
        prev.next = node
        self.size += 1

    def remove(self, index: int) -&gt; Any:
        if not 0 &lt;= index &lt; self.size:
            raise IndexError('index out of range')
        prev = self._prev_node(index)
        target = prev.next
        prev.next = target.next
        self.size -= 1
        return target.val

    def get(self, index: int) -&gt; Any:
        if not 0 &lt;= index &lt; self.size:
            raise IndexError('index out of range')
        cur = self.dummy.next
        for _ in range(index):
            cur = cur.next
        return cur.val

    def to_list(self) -&gt; list[Any]:
        result = []
        cur = self.dummy.next
        while cur:
            result.append(cur.val)
            cur = cur.next
        return result


