</pre> class ChainingHashTable:     def __init__(self, capacity: int = 8) -&gt; None:         self.capacity = max(4, capacity)         self.size = 0         self.buckets: list[list[list[Any]]] = [[] for _ in range(self.capacity)]      def _index(self, key: Any) -&gt; int:         return hash(key) % self.capacity      def _load_factor(self) -&gt; float:         return self.size / self.capacity      def _resize(self, new_capacity: int) -&gt; None:         old_items = self.items()         self.capacity = new_capacity         self.size = 0         self.buckets = [[] for _ in range(self.capacity)]         for key, value in old_items:             self.put(key, value)      def put(self, key: Any, value: Any) -&gt; None:         bucket = self.buckets[self._index(key)]         for pair in bucket:             if pair[0] == key:                 pair[1] = value                 return         bucket.append([key, value])         self.size += 1         if self._load_factor() &gt; 0.75:             self._resize(self.capacity * 2)      def get(self, key: Any, default: Any = None) -&gt; Any:         bucket = self.buckets[self._index(key)]         for pair in bucket:             if pair[0] == key:                 return pair[1]         return default      def remove(self, key: Any) -&gt; Any:         bucket = self.buckets[self._index(key)]         for i, pair in enumerate(bucket):             if pair[0] == key:                 self.size -= 1                 return bucket.pop(i)[1]         raise KeyError(key)      def items(self) -&gt; list[tuple[Any, Any]]:         result = []         for bucket in self.buckets:             for key, value in bucket:                 result.append((key, value))         return result   table = ChainingHashTable() table.put('alice', 3) table.put('bob', 5) table.put('alice', 8) removed = table.remove('bob')  {     'items': sorted(table.items()),     'removed': removed,     'get_alice': table.get('alice'), }  In [ ]: Copied! <pre>nums = [1, 2, 2, 3, 3, 3]

