def dfs(graph: dict[str, list[str]], start: str) -&gt; list[str]:
    visited = set()
    order = []

    def traverse(node: str) -&gt; None:
        visited.add(node)
        order.append(node)
        for nxt in graph[node]:
            if nxt not in visited:
